/**
 * TASK: Keep two linked sliders in balance.
 *
 * The "work" and "rest" sliders must ALWAYS add up to exactly 100. When one is
 * moved, the other has to follow.
 *   work moves to 70 -> rest becomes 30
 *   rest moves to 80 -> work becomes 20
 *
 * Complete sync(moved, other):
 *   1. If adjusting is already true, return at once -- you are being called
 *      back by your own setValue and must not answer it.
 *   2. Otherwise set adjusting to true, set the OTHER slider to
 *      100 - moved.getValue(), and set adjusting back to false.
 *   3. Finally call refresh() so the label shows the new split.
 *
 * Setting a slider's value fires its change listener immediately, so without
 * the adjusting flag the two listeners would call each other forever.
 */
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JSlider;

public class BudgetSliderPair extends JPanel {

    private final JSlider work = new JSlider(0, 100, 50);
    private final JSlider rest = new JSlider(0, 100, 50);
    private final JLabel split = new JLabel();
    private boolean adjusting = false;

    public BudgetSliderPair() {
        work.setName("work");
        rest.setName("rest");
        split.setName("split");
        add(work);
        add(rest);
        add(split);
        work.addChangeListener(e -> sync(work, rest));
        rest.addChangeListener(e -> sync(rest, work));
        refresh();
    }

    /** Provided: shows the current split. */
    private void refresh() {
        split.setText("Work " + work.getValue() + " / Rest " + rest.getValue());
    }

    private void sync(JSlider moved, JSlider other) {
        // TODO: guard against re-entry, mirror the value onto other, then refresh()
    }
}

