public class BudgetSliderPairTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    static java.awt.Component find(java.awt.Container root, String name) {
        if (name.equals(root.getName())) {
            return root;
        }
        for (java.awt.Component child : root.getComponents()) {
            if (name.equals(child.getName())) {
                return child;
            }
            if (child instanceof java.awt.Container) {
                java.awt.Component result = find((java.awt.Container) child, name);
                if (result != null) {
                    return result;
                }
            }
        }
        return null;
    }

    static String labelText(java.awt.Component c) {
        if (c instanceof javax.swing.JLabel) {
            return ((javax.swing.JLabel) c).getText();
        }
        return "(missing)";
    }

    static javax.swing.JSlider slider(java.awt.Container root, String name) {
        java.awt.Component c = find(root, name);
        return (c instanceof javax.swing.JSlider) ? (javax.swing.JSlider) c : null;
    }

    public static void main(String[] args) {
        try {
            BudgetSliderPair panel = new BudgetSliderPair();
            javax.swing.JSlider work = slider(panel, "work");
            javax.swing.JSlider rest = slider(panel, "rest");
            java.awt.Component split = find(panel, "split");
            check("both sliders found", true, work != null && rest != null);
            check("startup label", "Work 50 / Rest 50", labelText(split));
            if (work != null && rest != null) {
                work.setValue(70);
                check("rest follows work", 30, rest.getValue());
                check("label after moving work", "Work 70 / Rest 30", labelText(split));
                rest.setValue(80);
                check("work follows rest", 20, work.getValue());
                check("label after moving rest", "Work 20 / Rest 80", labelText(split));
                work.setValue(100);
                check("extreme value still balances", 0, rest.getValue());
                work.setValue(0);
                check("label at the other extreme", "Work 0 / Rest 100", labelText(split));
                check("values always add up to 100", 100, work.getValue() + rest.getValue());
            } else {
                failures++;
                System.out.println("FAIL  work or rest slider not found by name");
            }
        } catch (StackOverflowError e) {
            failures++;
            System.out.println("FAIL  the two listeners called each other forever -- use the adjusting flag");
        } catch (Exception e) {
            failures++;
            System.out.println("FAIL  unexpected exception: " + e);
        }
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

